ASSERT
  (SELECT preparation_contract_errors=0
   FROM
     (WITH input_summary AS
        (SELECT COUNT(*) AS input_rows, COUNT(DISTINCT p.request_id) AS distinct_requests, COUNT(DISTINCT p.full_input_rank) AS distinct_ranks, MIN(p.full_input_rank) AS first_rank, MAX(p.full_input_rank) AS last_rank, COUNT(DISTINCT p.new_input_rank) AS distinct_new_ranks, MIN(p.new_input_rank) AS first_new_rank, MAX(p.new_input_rank) AS last_new_rank, COUNTIF(p.cache_source_kind=1) AS cached_inputs, COUNTIF(p.cache_source_kind=0) AS new_inputs, COALESCE(SUM(IF(p.cache_source_kind=0, BYTE_LENGTH(p.model_input), 0)), 0) AS new_input_utf8_bytes, COALESCE(MAX(IF(p.cache_source_kind=0, BYTE_LENGTH(p.model_input), NULL)), 0) AS maximum_new_input_utf8_bytes, COUNTIF(p.model_input IS NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              OR p.model_input=''
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              OR BYTE_LENGTH(p.model_input)>6000
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              OR p.metadata_sha256 IS DISTINCT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              FROM LOWER(TO_HEX(SHA256(p.model_input)))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              OR p.request_id IS DISTINCT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              FROM LOWER(TO_HEX(SHA256(CONCAT('{"autoTruncate":false,"endpoint":"gemini-embedding-2","outputDimensionality":3072,"representation_version":"gkg-bq-metadata-v03-total-first-complete-labels-6000utf8","task_configuration":"service_default_no_task_parameter"}', '\n', p.metadata_sha256))))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              OR p.cache_source_kind IS NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              OR p.cache_source_kind NOT IN (0, 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              OR (p.cache_source_kind=1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  AND (p.batch_number IS DISTINCT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       FROM 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       OR p.new_input_rank IS NOT NULL))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              OR (p.cache_source_kind=0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  AND (p.new_input_rank IS NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       OR p.batch_number IS DISTINCT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       FROM 1+DIV(p.new_input_rank-1, 25000)))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              OR p.document_uses<=0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              OR p.first_corpus_rank NOT BETWEEN 1 AND 2000000) AS invalid_inputs
         FROM `${dataset}.filtered_dense_inputs_v01` AS p
         WHERE p.batch_number BETWEEN 0 AND 80), documents AS
        (SELECT COUNT(*) AS document_rows, COUNT(DISTINCT m.document_id) AS distinct_documents, COUNT(DISTINCT m.corpus_rank) AS distinct_ranks, MIN(m.corpus_rank) AS first_rank, MAX(m.corpus_rank) AS last_rank, COUNTIF(h.document_id IS NULL
                                                                                                                                                                                                                            OR p.request_id IS NULL
                                                                                                                                                                                                                            OR h.metadata_sha256 IS DISTINCT
                                                                                                                                                                                                                            FROM m.metadata_sha256
                                                                                                                                                                                                                            OR h.metadata_text IS DISTINCT
                                                                                                                                                                                                                            FROM p.model_input
                                                                                                                                                                                                                            OR p.metadata_sha256 IS DISTINCT
                                                                                                                                                                                                                            FROM m.metadata_sha256
                                                                                                                                                                                                                            OR h.corpus_rank IS DISTINCT
                                                                                                                                                                                                                            FROM m.corpus_rank
                                                                                                                                                                                                                            OR h.observed_day IS DISTINCT
                                                                                                                                                                                                                            FROM m.observed_day) AS document_binding_errors
         FROM `${dataset}.filtered_dense_documents_v01` AS m
         LEFT JOIN `${dataset}.corpus_documents` AS h ON h.document_id=m.document_id
         LEFT JOIN `${dataset}.filtered_dense_inputs_v01` AS p ON p.request_id=m.request_id
         AND p.batch_number BETWEEN 0 AND 80), actual_batches AS
        (SELECT p.batch_number AS batch_number, COUNT(*) AS expected_inputs, MIN(p.new_input_rank) AS first_new_rank, MAX(p.new_input_rank) AS last_new_rank, LOWER(TO_HEX(SHA256(STRING_AGG(CONCAT(p.request_id, '\t', p.metadata_sha256, '\n'), ''
                                                                                                                                                                                             ORDER BY p.new_input_rank)))) AS batch_sha256
         FROM `${dataset}.filtered_dense_inputs_v01` AS p
         WHERE p.batch_number BETWEEN 1 AND 80
         GROUP BY p.batch_number), batches AS
        (SELECT COUNT(b.batch_number) AS batch_count, COUNT(DISTINCT b.batch_number) AS distinct_batches, COALESCE(SUM(b.expected_inputs), 0) AS batch_expected_inputs, COALESCE(MAX(b.expected_inputs), 0) AS maximum_batch_inputs, COUNTIF(a.batch_number IS NULL
                                                                                                                                                                                                                                             OR b.batch_number IS NULL
                                                                                                                                                                                                                                             OR b.expected_inputs IS DISTINCT
                                                                                                                                                                                                                                             FROM a.expected_inputs
                                                                                                                                                                                                                                             OR b.input_cap IS DISTINCT
                                                                                                                                                                                                                                             FROM b.expected_inputs
                                                                                                                                                                                                                                             OR b.expected_inputs NOT BETWEEN 1 AND 25000
                                                                                                                                                                                                                                             OR b.first_new_rank IS DISTINCT
                                                                                                                                                                                                                                             FROM a.first_new_rank
                                                                                                                                                                                                                                             OR b.last_new_rank IS DISTINCT
                                                                                                                                                                                                                                             FROM a.last_new_rank
                                                                                                                                                                                                                                             OR b.first_new_rank IS DISTINCT
                                                                                                                                                                                                                                             FROM 1+(b.batch_number-1)*25000
                                                                                                                                                                                                                                             OR b.last_new_rank IS DISTINCT
                                                                                                                                                                                                                                             FROM b.first_new_rank+b.expected_inputs-1
                                                                                                                                                                                                                                             OR b.batch_sha256 IS DISTINCT
                                                                                                                                                                                                                                             FROM a.batch_sha256) AS batch_errors
         FROM `${dataset}.filtered_dense_batches_v01` AS b
         FULL OUTER JOIN actual_batches AS a ON a.batch_number=b.batch_number), cache AS
        (WITH raw_vectors AS
           (SELECT k.request_id AS request_id, 0 AS batch_number, '' AS status, k.embedding AS embedding
            FROM `${dataset}.filtered_dense_cache_v01` AS k), raw_checks AS
           (SELECT r.request_id AS request_id, r.batch_number AS batch_number, r.status AS status, r.embedding AS embedding, ARRAY_LENGTH(r.embedding) AS dimensions,
              (SELECT COUNTIF(x IS NULL
                              OR IS_NAN(x)
                              OR IS_INF(x))
               FROM UNNEST(r.embedding) AS x) AS invalid_components,
              (SELECT MAX(ABS(x))
               FROM UNNEST(r.embedding) AS x) AS scale
            FROM raw_vectors AS r), scaled_norms AS
           (SELECT r.request_id AS request_id, r.batch_number AS batch_number, r.status AS status, r.embedding AS embedding, r.dimensions AS dimensions, r.invalid_components AS invalid_components, IF(r.invalid_components=0
                                                                                                                                                                                                        AND r.scale>0
                                                                                                                                                                                                        AND NOT IS_NAN(r.scale)
                                                                                                                                                                                                        AND NOT IS_INF(r.scale), SAFE_MULTIPLY(r.scale, SQRT(
                                                                                                                                                                                                                                                               (SELECT SUM(POW(SAFE_DIVIDE(x, r.scale), 2))
                                                                                                                                                                                                                                                                FROM UNNEST(r.embedding) AS x))), NULL) AS vector_norm
            FROM raw_checks AS r), validated AS
           (SELECT n.request_id AS request_id, n.batch_number AS batch_number, n.status AS status, n.dimensions AS dimensions, n.invalid_components AS invalid_components, n.vector_norm AS vector_norm, COALESCE(n.status=''
                                                                                                                                                                                                                  AND n.dimensions=3072
                                                                                                                                                                                                                  AND n.invalid_components=0
                                                                                                                                                                                                                  AND n.vector_norm>0
                                                                                                                                                                                                                  AND NOT IS_NAN(n.vector_norm)
                                                                                                                                                                                                                  AND NOT IS_INF(n.vector_norm), FALSE) AS valid, LOWER(TO_HEX(SHA256(TO_JSON_STRING(n.embedding)))) AS vector_sha256
            FROM scaled_norms AS n), summary AS
           (SELECT COUNT(*) AS cache_rows, COUNT(DISTINCT k.request_id) AS distinct_cached_requests, COUNTIF(p.request_id IS NULL
                                                                                                             OR k.metadata_sha256 IS DISTINCT
                                                                                                             FROM p.metadata_sha256
                                                                                                             OR k.model_input IS DISTINCT
                                                                                                             FROM p.model_input
                                                                                                             OR k.source_kind IS DISTINCT
                                                                                                             FROM 1
                                                                                                             OR k.source_dataset IS DISTINCT
                                                                                                             FROM '${baseline_dataset}'
                                                                                                             OR k.vector_sha256 IS DISTINCT
                                                                                                             FROM LOWER(TO_HEX(SHA256(TO_JSON_STRING(k.embedding))))
                                                                                                             OR k.model_input IS NULL
                                                                                                             OR k.model_input=''
                                                                                                             OR BYTE_LENGTH(k.model_input)>6000
                                                                                                             OR k.metadata_sha256 IS DISTINCT
                                                                                                             FROM LOWER(TO_HEX(SHA256(k.model_input)))
                                                                                                             OR k.request_id IS DISTINCT
                                                                                                             FROM LOWER(TO_HEX(SHA256(CONCAT('{"autoTruncate":false,"endpoint":"gemini-embedding-2","outputDimensionality":3072,"representation_version":"gkg-bq-metadata-v03-total-first-complete-labels-6000utf8","task_configuration":"service_default_no_task_parameter"}', '\n', k.metadata_sha256))))) AS cache_binding_errors
            FROM `${dataset}.filtered_dense_cache_v01` AS k
            LEFT JOIN `${dataset}.filtered_dense_requests_v01` AS p ON p.request_id=k.request_id), norms AS
           (SELECT COUNTIF(NOT v.valid) AS invalid_cached_vectors
            FROM validated AS v) SELECT s.cache_rows AS cache_rows, s.distinct_cached_requests AS distinct_cached_requests, s.cache_binding_errors AS cache_binding_errors, n.invalid_cached_vectors AS invalid_cached_vectors, IF(s.cache_rows=s.distinct_cached_requests
                                                                                                                                                                                                                                   AND s.cache_binding_errors=0
                                                                                                                                                                                                                                   AND n.invalid_cached_vectors=0, 0, 1) AS cache_contract_errors
         FROM summary AS s
         CROSS JOIN norms AS n
         LIMIT 1), manifest AS
        (WITH input_blocks AS
           (SELECT DIV(p.full_input_rank-1, 1000) AS rank_block, COUNT(*) AS input_count, COUNTIF(p.cache_source_kind=1) AS cached_inputs, COUNTIF(p.cache_source_kind=0) AS new_inputs, LOWER(TO_HEX(SHA256(STRING_AGG(CONCAT(CAST(p.full_input_rank AS STRING), '\t', p.request_id, '\t', p.metadata_sha256, '\t', CAST(p.batch_number AS STRING), '\n'), ''
                                                                                                                                                                                                                        ORDER BY p.full_input_rank)))) AS block_sha256
            FROM `${dataset}.filtered_dense_inputs_v01` AS p
            WHERE p.batch_number BETWEEN 0 AND 80
            GROUP BY rank_block), input_fingerprint AS
           (SELECT COALESCE(SUM(b.input_count), 0) AS input_count, COALESCE(SUM(b.cached_inputs), 0) AS cached_inputs, COALESCE(SUM(b.new_inputs), 0) AS new_inputs, LOWER(TO_HEX(SHA256(COALESCE(STRING_AGG(CONCAT(CAST(b.rank_block AS STRING), '\t', b.block_sha256, '\n'), ''
                                                                                                                                                                                                             ORDER BY b.rank_block), '')))) AS inputs_sha256
            FROM input_blocks AS b), document_blocks AS
           (SELECT DIV(m.corpus_rank-1, 1000) AS rank_block, COUNT(*) AS document_count, LOWER(TO_HEX(SHA256(STRING_AGG(CONCAT(CAST(m.corpus_rank AS STRING), '\t', m.document_id, '\t', m.request_id, '\t', CAST(m.observed_day AS STRING), '\n'), ''
                                                                                                                        ORDER BY m.corpus_rank)))) AS block_sha256
            FROM `${dataset}.filtered_dense_documents_v01` AS m
            GROUP BY rank_block), document_fingerprint AS
           (SELECT COALESCE(SUM(b.document_count), 0) AS document_count, LOWER(TO_HEX(SHA256(COALESCE(STRING_AGG(CONCAT(CAST(b.rank_block AS STRING), '\t', b.block_sha256, '\n'), ''
                                                                                                                 ORDER BY b.rank_block), '')))) AS documents_sha256
            FROM document_blocks AS b), cache_blocks AS
           (SELECT SUBSTR(k.request_id, 1, 3) AS hash_block, COUNT(*) AS cache_count, LOWER(TO_HEX(SHA256(STRING_AGG(CONCAT(k.request_id, '\t', k.vector_sha256, '\n'), ''
                                                                                                                     ORDER BY k.request_id)))) AS block_sha256
            FROM `${dataset}.filtered_dense_cache_v01` AS k
            GROUP BY hash_block), cache_fingerprint AS
           (SELECT COALESCE(SUM(b.cache_count), 0) AS cache_count, LOWER(TO_HEX(SHA256(COALESCE(STRING_AGG(CONCAT(b.hash_block, '\t', b.block_sha256, '\n'), ''
                                                                                                           ORDER BY b.hash_block), '')))) AS cache_sha256
            FROM cache_blocks AS b) SELECT IF(COUNT(*)=1
                                              AND COUNTIF(m.contract_sha256=@contract_sha256
                                                          AND m.release='gkg-filtered-2m-dense-v01-r01'
                                                          AND m.embedding_spec_sha256='b935834ce400c38516af947df67c356c90f67bac60e0feb4e7ee4760c302e9f8'
                                                          AND m.embedding_spec_json='{"autoTruncate":false,"endpoint":"gemini-embedding-2","outputDimensionality":3072,"representation_version":"gkg-bq-metadata-v03-total-first-complete-labels-6000utf8","task_configuration":"service_default_no_task_parameter"}'
                                                          AND m.document_count=2000000
                                                          AND m.document_count=d.document_count
                                                          AND m.input_count=i.input_count
                                                          AND m.input_count BETWEEN 1 AND 2000000
                                                          AND m.cached_inputs=i.cached_inputs
                                                          AND m.cached_inputs=k.cache_count
                                                          AND m.new_inputs=i.new_inputs
                                                          AND m.input_count=m.cached_inputs+m.new_inputs
                                                          AND m.batch_size=25000
                                                          AND m.batch_count=DIV(m.new_inputs+25000-1, 25000)
                                                          AND m.inputs_sha256=i.inputs_sha256
                                                          AND m.documents_sha256=d.documents_sha256
                                                          AND m.cache_sha256=k.cache_sha256)=1, 0, 1) AS manifest_errors
         FROM `${dataset}.filtered_dense_manifest_v01` AS m
         CROSS JOIN input_fingerprint AS i
         CROSS JOIN document_fingerprint AS d
         CROSS JOIN cache_fingerprint AS k) SELECT d.document_rows AS document_rows, d.distinct_documents AS distinct_documents, i.input_rows AS input_rows, i.distinct_requests AS distinct_requests, i.cached_inputs AS cached_inputs, i.new_inputs AS new_inputs, b.batch_count AS batch_count, b.batch_expected_inputs AS batch_expected_inputs, b.maximum_batch_inputs AS maximum_batch_inputs, i.new_input_utf8_bytes AS new_input_utf8_bytes, i.maximum_new_input_utf8_bytes AS maximum_new_input_utf8_bytes, i.invalid_inputs AS invalid_inputs, k.cache_binding_errors AS cache_binding_errors, d.document_binding_errors AS document_binding_errors, b.batch_errors AS batch_errors, m.manifest_errors AS manifest_errors, IF(d.document_rows=2000000
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND d.distinct_documents=2000000
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND d.distinct_ranks=2000000
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND d.first_rank=1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND d.last_rank=2000000
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND d.document_binding_errors=0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND i.input_rows BETWEEN 1 AND 2000000
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND i.input_rows=i.distinct_requests
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND i.input_rows=i.distinct_ranks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND i.first_rank=1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND i.last_rank=i.input_rows
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND i.invalid_inputs=0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND i.input_rows=i.cached_inputs+i.new_inputs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND i.distinct_new_ranks=i.new_inputs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND (i.new_inputs=0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             OR (i.first_new_rank=1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 AND i.last_new_rank=i.new_inputs))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND k.cache_contract_errors=0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND k.cache_rows=i.cached_inputs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND b.batch_count=DIV(i.new_inputs+25000-1, 25000)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND b.distinct_batches=b.batch_count
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND b.batch_expected_inputs=i.new_inputs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND b.batch_errors=0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND m.manifest_errors=0, 0, 1) AS preparation_contract_errors
      FROM input_summary AS i
      CROSS JOIN documents AS d
      CROSS JOIN batches AS b
      CROSS JOIN cache AS k
      CROSS JOIN manifest AS m
      LIMIT 1)) AS 'Prepared input allocation or manifest does not satisfy the new filtered contract';
